INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 8, 'theory', 'Reliability and Congestion Control: Windows, Loss, Slow Start');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 8, 0, 'The receive window is 64 KB, the RTT is 100 ms. What is the approximate upper bound on speed?', '["about 50 Mbit/s", "about 500 Mbit/s", "about 5 Mbit/s", "limited only by the link"]', 2, 'Speed ≤ window / RTT = 64 KB / 0.1 s ≈ 640 KB/s ≈ 5 Mbit/s.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 8, 1, 'What happens to the congestion window in the slow start phase?', '["It doubles every RTT round", "It grows by one segment per RTT round", "It stays constant", "It is cut in half"]', 0, 'Each ACK adds a segment, so the window doubles in one RTT.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 8, 2, 'How does classic Reno react to a segment loss detected by three identical ACKs?', '["Closes the connection", "Doubles the window", "Resets the window to one segment", "Halves the window"]', 3, 'This is the multiplicative decrease (AIMD): ÷ 2. The window is reset to one segment only on a timeout.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 8, 3, 'What is the main difference between BBR and CUBIC?', '["BBR uses UDP", "BBR measures the bandwidth and delay of the link and barely reacts to loss", "BBR works only over IPv6", "BBR needs no acknowledgments"]', 1, 'That is why BBR is good on links where loss is not tied to congestion: Wi-Fi, mobile networks, satellite.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 8, 4, 'What is bufferbloat?', '["A queue swelling at a bottleneck: no loss, but huge delay", "A shortage of memory in the browser", "Fragmentation of large packets", "A checksum error"]', 0, 'A buffer that is too big fills to the brim, and every packet waits in the queue for hundreds of milliseconds.');
